-- 210: Original BrillaPrep WASSCE BrillaPrep transitional Leatherwork beta content blueprint questions, part 8.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_210_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_210_guard;
INSERT INTO _migration_210_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_029' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_6' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What method helps fix a bag gusset accurately before permanent stitching?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Drive permanent rivets through unverified positions before aligning the curved seam","B. Secure one end permanently and stretch the gusset until the other end reaches its mark","C. Match centre and notch marks, then hold the aligned seam progressively with clips or temporary compatible adhesive","D. Trim the gusset repeatedly during stitching whenever the notches stop matching"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Matched reference marks distribute gusset length around curves, while progressive temporary fixing prevents creep and lets the maker confirm alignment before committing the seam. Therefore the correct answer is C: Match centre and notch marks, then hold the aligned seam progressively with clips or temporary compatible adhesive.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_6' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_029' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_210_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_030' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_6' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How is a suitable rivet post length selected for a leather joint?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Measure the metal cap diameter because it determines the required post length","B. Allow for the complete material stack plus enough post to form the specified set","C. Use the longest available post and tighten it until the leather stops compressing","D. Choose a post flush with the first layer before the remaining layers are added"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The post must pass through leather, lining and reinforcement and still provide the maker-recommended forming allowance without excessive protrusion, bending or crushing. Therefore the correct answer is B: Allow for the complete material stack plus enough post to form the specified set.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_6' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_030' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_210_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_031' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_7' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is vegetable-tanned leather lightly cased before carving or stamping?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Controlled moisture makes the fibres accept and retain compressed detail","B. Full soaking keeps impressions sharp because the fibres cannot move","C. Casing applies the final water-resistant coating before decoration","D. A dry surface lets the tool compress fibres more evenly without drag"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Evenly dampened vegetable-tanned leather becomes receptive to modelling and then firms as it dries; material that is too dry or saturated gives poor control and definition. Therefore the correct answer is A: Controlled moisture makes the fibres accept and retain compressed detail.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_7' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_031' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_210_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_032' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_7' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which statement correctly distinguishes dyeing from tanning in leather production?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Dyeing introduces colour into prepared leather, whereas tanning chemically stabilises the hide fibres against decay","B. Dyeing stabilises raw collagen, whereas tanning adds a removable surface colour","C. Dyeing and tanning are two names for applying pigment after the leather has dried","D. Tanning removes grease before colouring, whereas dyeing replaces the beamhouse operations"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Tanning converts a perishable hide or skin into a more durable material by stabilising collagen. Dyeing is a later or integrated colouring operation and does not replace the chemical protection supplied by tannage. Therefore the correct answer is A: Dyeing introduces colour into prepared leather, whereas tanning chemically stabilises the hide fibres against decay.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_7' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_032' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_029', 'topic_was_leatherwork_b004_6', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'What method helps fix a bag gusset accurately before permanent stitching?', 'multiple_choice', NULL, '["A. Drive permanent rivets through unverified positions before aligning the curved seam","B. Secure one end permanently and stretch the gusset until the other end reaches its mark","C. Match centre and notch marks, then hold the aligned seam progressively with clips or temporary compatible adhesive","D. Trim the gusset repeatedly during stitching whenever the notches stop matching"]', 'C', 'Matched reference marks distribute gusset length around curves, while progressive temporary fixing prevents creep and lets the maker confirm alignment before committing the seam. Therefore the correct answer is C: Match centre and notch marks, then hold the aligned seam progressively with clips or temporary compatible adhesive.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_6', 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_030', 'topic_was_leatherwork_b004_6', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'How is a suitable rivet post length selected for a leather joint?', 'multiple_choice', NULL, '["A. Measure the metal cap diameter because it determines the required post length","B. Allow for the complete material stack plus enough post to form the specified set","C. Use the longest available post and tighten it until the leather stops compressing","D. Choose a post flush with the first layer before the remaining layers are added"]', 'B', 'The post must pass through leather, lining and reinforcement and still provide the maker-recommended forming allowance without excessive protrusion, bending or crushing. Therefore the correct answer is B: Allow for the complete material stack plus enough post to form the specified set.', 'hard', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_6', 'Explain', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_031', 'topic_was_leatherwork_b004_7', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'Why is vegetable-tanned leather lightly cased before carving or stamping?', 'multiple_choice', NULL, '["A. Controlled moisture makes the fibres accept and retain compressed detail","B. Full soaking keeps impressions sharp because the fibres cannot move","C. Casing applies the final water-resistant coating before decoration","D. A dry surface lets the tool compress fibres more evenly without drag"]', 'A', 'Evenly dampened vegetable-tanned leather becomes receptive to modelling and then firms as it dries; material that is too dry or saturated gives poor control and definition. Therefore the correct answer is A: Controlled moisture makes the fibres accept and retain compressed detail.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_7', 'Explain', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_032', 'topic_was_leatherwork_b004_7', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'Which statement correctly distinguishes dyeing from tanning in leather production?', 'multiple_choice', NULL, '["A. Dyeing introduces colour into prepared leather, whereas tanning chemically stabilises the hide fibres against decay","B. Dyeing stabilises raw collagen, whereas tanning adds a removable surface colour","C. Dyeing and tanning are two names for applying pigment after the leather has dried","D. Tanning removes grease before colouring, whereas dyeing replaces the beamhouse operations"]', 'A', 'Tanning converts a perishable hide or skin into a more durable material by stabilising collagen. Dyeing is a later or integrated colouring operation and does not replace the chemical protection supplied by tannage. Therefore the correct answer is A: Dyeing introduces colour into prepared leather, whereas tanning chemically stabilises the hide fibres against decay.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_7', 'Identify', 'AO2', NULL, NULL, 'board_waec');
